class Node:
    def __init__(self, val=None, children=None):
        self.val = val
        self.children = children if children is not None else []

def moveSubTree(root: 'Node', p: 'Node', q: 'Node') -> 'Node':
    # p already a direct child of q: nothing to do
    if p in q.children:
        return root

    # Build parent map (iterative DFS)
    parent = {root: None}
    stack = [root]
    while stack:
        node = stack.pop()
        for child in node.children:
            parent[child] = node
            stack.append(child)

    # Is q inside the subtree of p? Walk up from q.
    cur = q
    while cur is not None and cur is not p:
        cur = parent[cur]
    q_in_p = cur is p

    p_parent = parent[p]
    if q_in_p:
        # Case 1: detach q, put q where p was, then hang p under q
        parent[q].children.remove(q)
        if p_parent is None:
            root = q
        else:
            idx = p_parent.children.index(p)
            p_parent.children[idx] = q
        q.children.append(p)
    else:
        # Cases 2 and 3: move p under q as its last child
        p_parent.children.remove(p)
        q.children.append(p)
    return root
